head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > setInterval]<br/>함수를 setInterval 로 등록하여 주기적으로 반복 실행되도록 합니다.",
    "validation" : [
        "func(필수) 파라미터로 주기적으로 실행할 함수를 설정할 수 있어야 합니다.",
        "options(선택) 파라미터로 Interval 옵션을 설정할 수 있어야 합니다.",
        "options.key(선택) 파라미터로 Interval 을 식별하기 위한 고유 키를 설정할 수 있어야 합니다.",
        "options.key(선택) 파라미터를 설정하지 않으면 func 파라미터의 함수를 문자열로 변환한 뒤 앞 30 자를 키값으로 사용해야 합니다.",
        "동일 키로 이미 Interval 이 등록된 경우 기존 Interval 을 clearInterval 로 해제한 후 새로 등록해야 합니다.",
        "options.delay(선택) 파라미터로 실행 간격을 밀리초 단위로 설정할 수 있어야 합니다.",
        "options.delay(선택) 파라미터 생략 시 기본값 1 로 동작해야 합니다.",
        "options.caller(선택) 파라미터로 func 내에서 this 로 사용될 객체를 설정할 수 있어야 합니다.",
        "options.args(선택) 파라미터가 설정되어 있고 options.caller(선택) 파라미터가 설정되지 않으면 window 가 기본값으로 사용되어야 합니다.",
        "options.args(선택) 파라미터로 func 에 전달할 인자 배열을 설정할 수 있어야 합니다.",
        "등록된 Interval 의 키 값을 반환해야 합니다.",
        "SPA 모드에서 페이지 이동 시 이 메소드로 등록한 Interval 이 자동으로 제거되어야 합니다.",
    ]
}

scwin.intervalCount = 0;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    var keyList = $p.getIntervalKeyList();
    if (keyList.length > 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[페이지 로드] 잔존 IntervalKeyList : " + JSON.stringify(keyList));
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("[페이지 로드] IntervalKeyList : 비어있음 (Interval 자동 제거 확인)");
    }
};



scwin.fn_Interval = function (arg1, arg2) {
    scwin.intervalCount++;
    var msg = "실행 " + scwin.intervalCount + "회";
    if (arg1 !== undefined) {
        msg += " / arg1: " + arg1;
    }
    if (arg2 !== undefined) {
        msg += " / arg2: " + arg2;
    }
    msg += " / this: " + (this === window ? "window" : this.id || JSON.stringify(this));
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};



scwin.btn_setInterval_onclick = function () {
    var key = par_key.getValue();
    var delay = par_delay.getValue();
    var useCaller = par_caller.getValue();
    var useArgs = par_args.getValue();

    scwin.intervalCount = 0;

    var options = {};

    if (key !== "") {
        options.key = key;
    }

    if (delay !== "") {
        options.delay = Number(delay);
    }

    if (useCaller === "true") {
        options.caller = {id: "callerObj"};
    }

    if (useArgs === "true") {
        options.args = ["인자1", "인자2"];
    }

    var resultKey = $p.setInterval(scwin.fn_Interval, options);

    wf_body_bottom.getObj("scwin").setReturnValue("반환 키 : " + resultKey);
    wf_body_bottom.getObj("scwin").setReturnValue("getIntervalKeyList : " + JSON.stringify($p.getIntervalKeyList()));
}



scwin.btn_clearInterval_onclick = function () {
    var key = par_key.getValue();
    if (key === "") {
        var keyList = $p.getIntervalKeyList();
        if (keyList.length > 0) {
            key = keyList[0];
        }
    }

    $p.clearInterval(key);
    wf_body_bottom.getObj("scwin").setReturnValue("clearInterval('" + key + "') 실행");
    wf_body_bottom.getObj("scwin").setReturnValue("getIntervalKeyList : " + JSON.stringify($p.getIntervalKeyList()));
}



scwin.btn_reinitialize_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("reinitialize 실행 → 페이지 새로고침 후 IntervalKeyList 확인");
    $p.reinitialize();
}
